export const CATEGORIES = [
  { id: "all", label: "All" },
  { id: "coffee", label: "Coffee" },
  { id: "beans", label: "Beans" },
  { id: "gear", label: "Gear" },
  { id: "snacks", label: "Snacks" },
  { id: "mugs", label: "Mugs" }
];

export const FILTERS = [
  { id: "all", label: "All" },
  { id: "new", label: "New" },
  { id: "sale", label: "Sale" },
  { id: "popular", label: "Popular" },
  { id: "under20", label: "Under $20" }
];

export const PRODUCT_CATEGORY_VALUES = ["coffee", "beans", "gear", "snacks", "mugs"];

/** @param {Record<string, unknown>} p */
export function productMatchesFilter(p, filId) {
  const tags = /** @type {string[]} */ (p.tags || []);
  if (filId === "all") return true;
  if (filId === "new") return tags.includes("new");
  if (filId === "sale")
    return tags.includes("sale") || (p.compareAtPrice != null && Number(p.compareAtPrice) > Number(p.price));
  if (filId === "popular") return tags.includes("popular");
  if (filId === "under20") return Number(p.price) < 20;
  return true;
}

/** @param {string} id */
export function refFromId(id) {
  let x = 0;
  for (let i = 0; i < id.length; i++) x = (x * 31 + id.charCodeAt(i)) >>> 0;
  return (x % 59) + 1;
}

/** @param {Record<string, unknown>} p */
export function productBadge(p) {
  const tags = /** @type {string[]} */ (p.tags || []);
  if (tags.includes("sale")) return "Sale";
  if (tags.includes("new")) return "New";
  if (tags.includes("popular")) return "Popular";
  return null;
}
